PROGRAM MotorDiag
VAR_INPUT StartPB AT %I0.0 : BOOL; StopOK AT %I0.1 : BOOL; OverloadOK AT %I0.2 : BOOL; END_VAR
VAR_OUTPUT Motor AT %Q0.0 : BOOL; Alarm AT %Q0.1 : BOOL; END_VAR
Motor := (StartPB OR Motor) AND StopOK AND OverloadOK;
Alarm := NOT OverloadOK;
END_PROGRAM

